// 8.2.1. Layering and Module Structure.
//
// Software layering (presentation, business logic, data access, infrastructure)
// and module structure (bounded contexts, packages, libraries).
export class LayeringAndModuleStructure extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get content(): string {
    return this.doc.content(this.path + "/content") || '';
  }

  set content(value: string) {
    this.doc.setContent(this.path + "/content", value);
  }

  // Overview of the layering and modularization approach.
  // (skipped: overview has no target type)

  // Software layer definitions.
  get softwareLayers(): SomList<SoftwareLayerEntry> {
    return new SomList(this.doc, this.path + "/SOLAEN-SOFT-LST", (d: SpecDocument, p: string) => new SoftwareLayerEntry(d, p));
  }

  // Layer communication rules and constraints.
  get layerCommunicationRules(): LayerCommunicationRules {
    return new LayerCommunicationRules(this.doc, this.path + "/layerCommunicationRules");
  }

  // Bounded contexts (DDD) definitions.
  get boundedContexts(): SomList<BoundedContextEntry> {
    return new SomList(this.doc, this.path + "/BOCOEN-BOUN-LST", (d: SpecDocument, p: string) => new BoundedContextEntry(d, p));
  }

  // Package organization and structure.
  get packageOrganization(): PackageOrganization {
    return new PackageOrganization(this.doc, this.path + "/packageOrganization");
  }

  // Module catalog with dependency information.
  get modules(): SomList<ModuleEntry> {
    return new SomList(this.doc, this.path + "/MOEN1-MODU-LST", (d: SpecDocument, p: string) => new ModuleEntry(d, p));
  }

  // Shared libraries and common code.
  get sharedLibraries(): SomList<SharedLibraryEntry> {
    return new SomList(this.doc, this.path + "/SHLIB-SHAR-LST", (d: SpecDocument, p: string) => new SharedLibraryEntry(d, p));
  }

  // Dependency injection configuration.
  get dependencyInjection(): DependencyInjectionStructure {
    return new DependencyInjectionStructure(this.doc, this.path + "/dependencyInjection");
  }

  // Cross-cutting concerns organization.
  get crossCuttingConcerns(): CrossCuttingConcerns {
    return new CrossCuttingConcerns(this.doc, this.path + "/crossCuttingConcerns");
  }

  // Feature module definitions (vertical slices).
  get featureModules(): SomList<FeatureModuleEntry> {
    return new SomList(this.doc, this.path + "/FTRMOD-FEAT-LST", (d: SpecDocument, p: string) => new FeatureModuleEntry(d, p));
  }

  // Module versioning and compatibility strategy.
  get moduleVersioningStrategy(): ModuleVersioningStrategy {
    return new ModuleVersioningStrategy(this.doc, this.path + "/moduleVersioningStrategy");
  }
}

