// 9.2.3. Password and Credential Policy.
//
// Comprehensive password and credential policy aligned with NIST SP 800-63B
// (Revision 4). Covers password requirements, storage, lifecycle, account
// lockout, credential recovery, MFA enforcement per user category,
// credential compromise detection, and service account credential management.
export class PasswordAndCredentialPolicy extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get content(): string {
    return this.doc.content(this.path + "/content") || '';
  }

  set content(value: string) {
    this.doc.setContent(this.path + "/content", value);
  }

  // Password and Credential Policy Overview (text).
  // (skipped: overview has no target type)

  // Password Requirements.
  get passwordRequirements(): PasswordRequirementsPolicy {
    return new PasswordRequirementsPolicy(this.doc, this.path + "/passwordRequirements");
  }

  // Password Storage and Verification.
  get passwordStorage(): PasswordStoragePolicy {
    return new PasswordStoragePolicy(this.doc, this.path + "/passwordStorage");
  }

  // Password Lifecycle.
  get passwordLifecycle(): PasswordLifecyclePolicy {
    return new PasswordLifecyclePolicy(this.doc, this.path + "/passwordLifecycle");
  }

  // Account Lockout and Throttling.
  get accountLockout(): AccountLockoutPolicy {
    return new AccountLockoutPolicy(this.doc, this.path + "/accountLockout");
  }

  // Credential Recovery.
  get credentialRecovery(): CredentialRecoveryPolicy {
    return new CredentialRecoveryPolicy(this.doc, this.path + "/credentialRecovery");
  }

  // Credential Compromise Detection.
  get compromiseDetection(): CredentialCompromiseDetectionPolicy {
    return new CredentialCompromiseDetectionPolicy(this.doc, this.path + "/compromiseDetection");
  }

  // Service Account and API Credential Policy.
  get serviceAccountCredentials(): ServiceAccountCredentialPolicy {
    return new ServiceAccountCredentialPolicy(this.doc, this.path + "/serviceAccountCredentials");
  }

  // Contains 0+× MFA Enforcement per User Category.
  get mfaCategoryRequirements(): SomList<MfaCategoryRequirementEntry> {
    return new SomList(this.doc, this.path + "/MFACRQ-MFAC-LST", (d: SpecDocument, p: string) => new MfaCategoryRequirementEntry(d, p));
  }
}

