// A scenario entry.
//
// Comprehensive scenario definition for end-to-end user journey.
export class ScenarioEntry extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  // Scenario identification.
  get identification(): ScenarioIdentification {
    return new ScenarioIdentification(this.doc, this.path + "/identification");
  }

  // Scenario context.
  get context(): ScenarioContext {
    return new ScenarioContext(this.doc, this.path + "/context");
  }

  // Contains 1+× Scenario Step.
  get steps(): SomList<ScenarioStepEntry> {
    return new SomList(this.doc, this.path + "/SCNST-STEP-LST", (d: SpecDocument, p: string) => new ScenarioStepEntry(d, p));
  }

  // Alternative flows — contains 0+× Alternative Flow.
  get alternativeFlows(): SomList<AlternativeFlowEntry> {
    return new SomList(this.doc, this.path + "/ALFL-ALTE-LST", (d: SpecDocument, p: string) => new AlternativeFlowEntry(d, p));
  }

  // Scenario data.
  get scenarioData(): ScenarioData {
    return new ScenarioData(this.doc, this.path + "/scenarioData");
  }

  // Scenario timing.
  get timing(): ScenarioTiming {
    return new ScenarioTiming(this.doc, this.path + "/timing");
  }

  // Scenario validation.
  get validation(): ScenarioValidation {
    return new ScenarioValidation(this.doc, this.path + "/validation");
  }
}

